const svgNS = 'http://www.w3.org/2000/svg';

function makeIcon(d) {
  const svg = document.createElementNS(svgNS, 'svg');
  svg.setAttribute('viewBox', '0 0 24 24');
  svg.setAttribute('width', '16');
  svg.setAttribute('height', '16');
  const path = document.createElementNS(svgNS, 'path');
  path.setAttribute('d', d);
  svg.appendChild(path);
  return svg;
}

function makeChip(label, iconD, param) {
  const chip = document.createElement('div');
  chip.className = 'yt-ext-fp-chip';
  chip.dataset.param = param;
  chip.title = label;
  chip.appendChild(makeIcon(iconD));
  const sp = document.createElement('span');
  sp.className = 'chip-label';
  sp.textContent = label;
  chip.appendChild(sp);
  return chip;
}

function makeSection(header, chips) {
  const sec = document.createElement('div');
  sec.className = 'yt-ext-fp-section';
  const h = document.createElement('div');
  h.className = 'yt-ext-fp-section-header';
  h.textContent = header;
  sec.appendChild(h);
  const wrap = document.createElement('div');
  wrap.className = 'yt-ext-fp-chips';
  chips.forEach(function(c) { wrap.appendChild(makeChip(c.label, c.icon, c.param)); });
  sec.appendChild(wrap);
  return sec;
}

